(()=>{const nav=document.querySelector('.case-layout aside');if(!nav||!('IntersectionObserver'in window))return;const links=[...nav.querySelectorAll('a[href^="#"]')];const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){links.forEach(a=>{if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}}),{rootMargin:'-15% 0px -50% 0px'});document.querySelectorAll('.case-story section[id]').forEach(s=>observer.observe(s))})();
